'use client';

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useId, useState } from 'react';

import {
  ChevronRightIcon,
  SettingsIcon,
  UserRoundPlusIcon,
  XIcon,
} from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';
import { Button } from '@/registry/ndeko/ui/button';
import { ToggleGroup, ToggleGroupItem } from '@/registry/ndeko/ui/toggle-group';

import { ActivityFeed } from './activity-feed';
import {
  ACTIVITY,
  FIGURES,
  MEMBERS,
  PERIOD_LABELS,
  TEAM,
  WORKSPACE_NAME,
  type Period,
} from './data';
import { MemberList } from './member-list';
import { formatMinutes, SlidingFigure, TeamTile } from './parts';

const PERIODS: Period[] = ['this', 'last'];

const THUMB =
  'bg-card shadow-[0_1px_2px_rgb(0_0_0/0.08)] hairline-ring ring-foreground/10 dark:bg-foreground/[0.09] dark:ring-foreground/15';

const SURFACE =
  'bg-card hairline-ring ring-border rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]';

const ARRIVE: Transition = { duration: 0.18, ease: [0.23, 1, 0.32, 1] };
const LEAVE: Transition = { duration: 0.12, ease: [0.23, 1, 0.32, 1] };

const BLUR_VARIANTS: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)', transition: ARRIVE },
  exit: { opacity: 0, filter: 'blur(2px)', transition: LEAVE },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1, transition: ARRIVE },
  exit: { opacity: 0, transition: LEAVE },
};

function blurOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return BLUR_VARIANTS;
}

function isPeriod(value: unknown): value is Period {
  return PERIODS.some((period) => period === value);
}

function countOf(value: number) {
  return String(value);
}

function trackingLabelOf(count: number) {
  return `${count} of ${MEMBERS.length}`;
}

function activityTitleOf(memberName: string | null) {
  if (memberName === null) {
    return 'Recent activity';
  }
  return `Activity of ${memberName}`;
}

function memberNameOf(memberId: string | null) {
  const member = MEMBERS.find((candidate) => candidate.id === memberId);
  if (member) {
    return member.name;
  }
  return null;
}

type FigureProps = {
  label: string;
  value: number;
  format: (value: number) => string;
};

function Figure({ label, value, format }: FigureProps) {
  return (
    <div className='flex min-w-0 flex-col gap-0.5'>
      <dt className='text-muted-foreground text-xs'>{label}</dt>
      <dd className='text-lg font-semibold'>
        <SlidingFigure value={value} format={format} />
      </dd>
    </div>
  );
}

function TeamHead() {
  const faces = MEMBERS.slice(0, 4);
  const restCount = MEMBERS.length - faces.length;

  return (
    <div className='flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between'>
      <div className='flex min-w-0 items-start gap-3'>
        <TeamTile initials={TEAM.initials} color={TEAM.color} />
        <div className='min-w-0'>
          <h1 className='text-lg font-semibold'>{TEAM.name}</h1>
          <p className='text-muted-foreground text-[13px] text-balance'>
            {TEAM.description}
          </p>
        </div>
      </div>
      <div className='flex shrink-0 items-center gap-3'>
        <span className='flex items-center ps-1.5'>
          {faces.map((member) => (
            <Avatar
              key={member.id}
              className='ring-background -ms-1.5 size-7 text-[10px] ring-2'
            >
              {member.avatar && <AvatarImage src={member.avatar} alt='' />}
              <AvatarFallback>{member.initials}</AvatarFallback>
            </Avatar>
          ))}
          <span className='bg-muted text-muted-foreground ring-background -ms-1.5 inline-flex h-7 min-w-7 items-center justify-center rounded-full px-1 text-[10px] font-medium tabular-nums ring-2'>
            +{restCount}
          </span>
        </span>
        <Button variant='outline' size='sm'>
          <UserRoundPlusIcon />
          Invite
        </Button>
        <Button
          variant='ghost'
          size='icon-sm'
          aria-label='Team settings'
          className='text-muted-foreground'
        >
          <SettingsIcon />
        </Button>
      </div>
    </div>
  );
}

export default function Team04() {
  const shouldReduceMotion = useReducedMotion();
  const membersTitleId = useId();
  const [period, setPeriod] = useState<Period>('this');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const figures = FIGURES[period];
  const trackingCount = MEMBERS.filter(
    (member) => member.presence === 'tracking'
  ).length;
  const selectedName = memberNameOf(selectedId);
  const hasSelection = selectedName !== null;
  const activityTitle = activityTitleOf(selectedName);
  const activity = ACTIVITY.filter((item) => {
    if (selectedId === null) {
      return true;
    }
    return item.memberId === selectedId;
  });
  const pressedPeriods = [period];

  function changePeriod(values: unknown[]) {
    const [value] = values;
    if (isPeriod(value)) {
      setPeriod(value);
    }
  }

  function toggleMember(memberId: string) {
    setSelectedId((current) => {
      if (current === memberId) {
        return null;
      }
      return memberId;
    });
  }

  function showEveryone() {
    setSelectedId(null);
  }

  return (
    <div className='bg-background text-foreground flex min-h-svh w-full flex-col'>
      <header className='hairline-b border-border flex h-11 shrink-0 items-center gap-3 px-3 sm:px-5'>
        <nav
          aria-label='Breadcrumb'
          className='flex min-w-0 items-center gap-1.5 text-[13px]'
        >
          <span className='text-muted-foreground'>{WORKSPACE_NAME}</span>
          <ChevronRightIcon className='text-muted-foreground size-3.5' />
          <span className='text-muted-foreground'>Teams</span>
          <ChevronRightIcon className='text-muted-foreground size-3.5' />
          <span className='truncate font-medium'>{TEAM.name}</span>
        </nav>
      </header>
      <main className='mx-auto flex w-full max-w-6xl flex-col gap-6 px-4 py-6 md:px-6'>
        <TeamHead />
        <section aria-label='Figures' className='flex flex-col gap-3'>
          <ToggleGroup
            aria-label='Period'
            value={pressedPeriods}
            onValueChange={changePeriod}
            travel
            size='sm'
            indicatorClassName={THUMB}
            className='bg-foreground/[0.05] rounded-lg p-0.5'
          >
            {PERIODS.map((value) => (
              <ToggleGroupItem
                key={value}
                value={value}
                className='h-6 rounded-md px-2.5 text-xs'
              >
                {PERIOD_LABELS[value]}
              </ToggleGroupItem>
            ))}
          </ToggleGroup>
          <dl className='grid grid-cols-2 gap-x-6 gap-y-4 sm:grid-cols-4'>
            <Figure
              label='Open tasks'
              value={figures.openTasks}
              format={countOf}
            />
            <Figure label='Done' value={figures.doneTasks} format={countOf} />
            <Figure
              label='Tracked'
              value={figures.trackedMinutes}
              format={formatMinutes}
            />
            <Figure
              label='Tracking now'
              value={trackingCount}
              format={trackingLabelOf}
            />
          </dl>
        </section>
        <div className='grid gap-6 lg:grid-cols-[minmax(0,1.5fr)_minmax(0,1fr)]'>
          <section aria-labelledby={membersTitleId} className={SURFACE}>
            <div className='flex items-baseline justify-between gap-3 px-4 pt-4 pb-2'>
              <h2 id={membersTitleId} className='text-sm font-medium'>
                Members
              </h2>
              <p className='text-muted-foreground text-xs'>
                Pick someone to see their activity
              </p>
            </div>
            <div className='px-1.5 pb-1.5'>
              <MemberList
                members={MEMBERS}
                period={period}
                selectedId={selectedId}
                onToggle={toggleMember}
              />
            </div>
          </section>
          <section aria-label='Activity' className={SURFACE}>
            <div className='flex min-h-12 items-center justify-between gap-3 px-4 pt-2'>
              <h2 className='text-sm font-medium'>
                <AnimatedSize as='span' axis='width'>
                  <AnimatePresence mode='popLayout' initial={false}>
                    <motion.span
                      key={activityTitle}
                      variants={blurOf(shouldReduceMotion)}
                      initial='enter'
                      animate='visible'
                      exit='exit'
                      className='block whitespace-nowrap'
                    >
                      {activityTitle}
                    </motion.span>
                  </AnimatePresence>
                </AnimatedSize>
              </h2>
              <AnimatePresence initial={false}>
                {hasSelection && (
                  <motion.span
                    key='clear'
                    variants={blurOf(shouldReduceMotion)}
                    initial='enter'
                    animate='visible'
                    exit='exit'
                  >
                    <Button
                      variant='ghost'
                      size='sm'
                      onClick={showEveryone}
                      className='text-muted-foreground'
                    >
                      <XIcon />
                      Show everyone
                    </Button>
                  </motion.span>
                )}
              </AnimatePresence>
            </div>
            <div className='px-4 pt-2 pb-2'>
              <ActivityFeed activity={activity} />
            </div>
          </section>
        </div>
      </main>
    </div>
  );
}

'use client';

import { motion, useReducedMotion, type Transition } from 'motion/react';
import { useId } from 'react';

import type { Member, Period } from './data';
import {
  formatMinutes,
  IssueTypeGem,
  PresenceAvatar,
  ROLE_LABELS,
  SlidingFigure,
} from './parts';

const WEEK_TARGET_MINUTES = 2400;

const TRAVEL: Transition = { type: 'spring', bounce: 0, duration: 0.3 };

const INSTANT: Transition = { duration: 0 };

function travelOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return TRAVEL;
}

function shareOf(minutes: number) {
  const share = minutes / WEEK_TARGET_MINUTES;
  return Math.min(1, share);
}

function MemberTaskCell({ member }: { member: Member }) {
  const task = member.task;
  if (!task) {
    return (
      <span className='text-muted-foreground text-xs'>No task in progress</span>
    );
  }
  return (
    <span className='flex min-w-0 items-center gap-1.5'>
      <IssueTypeGem type={task.type} />
      <span className='text-muted-foreground shrink-0 text-xs tabular-nums'>
        {task.key}
      </span>
      <span className='truncate text-[13px]'>{task.title}</span>
    </span>
  );
}

type MemberRowProps = {
  member: Member;
  period: Period;
  isSelected: boolean;
  indicatorId: string;
  onToggle: (memberId: string) => void;
};

function MemberRow({
  member,
  period,
  isSelected,
  indicatorId,
  onToggle,
}: MemberRowProps) {
  const shouldReduceMotion = useReducedMotion();
  const minutes = member.minutes[period];
  const share = shareOf(minutes);
  const barStyle = { transform: `scaleX(${share})` };

  return (
    <li className='relative'>
      {isSelected && (
        <motion.span
          layoutId={indicatorId}
          aria-hidden='true'
          transition={travelOf(shouldReduceMotion)}
          className='bg-foreground/[0.05] absolute inset-0 rounded-lg'
        />
      )}
      <button
        type='button'
        aria-pressed={isSelected}
        onClick={() => onToggle(member.id)}
        className='hover:bg-foreground/[0.03] focus-visible:ring-ring/25 relative grid w-full cursor-pointer grid-cols-[minmax(0,1fr)_5.5rem] items-center gap-x-4 gap-y-1 rounded-lg px-3 py-2.5 text-left outline-none focus-visible:ring-[3px] md:grid-cols-[minmax(0,13rem)_minmax(0,1fr)_7rem]'
      >
        <span className='flex min-w-0 items-center gap-3'>
          <PresenceAvatar member={member} />
          <span className='min-w-0'>
            <span className='block truncate text-[13px] leading-5 font-medium'>
              {member.name}
            </span>
            <span className='text-muted-foreground block truncate text-xs'>
              {ROLE_LABELS[member.role]} · {member.title}
            </span>
          </span>
        </span>
        <span className='col-span-2 row-start-2 min-w-0 ps-11 md:col-span-1 md:row-start-1 md:ps-0'>
          <MemberTaskCell member={member} />
        </span>
        <span className='flex flex-col items-end gap-1.5'>
          <SlidingFigure
            value={minutes}
            format={formatMinutes}
            className='text-[13px] font-medium'
          />
          <span
            aria-hidden='true'
            className='bg-foreground/[0.06] block h-1 w-full overflow-hidden rounded-full'
          >
            <span
              style={barStyle}
              className='bg-primary block h-full origin-left rounded-full transition-transform duration-300 ease-(--ease-out-strong)'
            />
          </span>
        </span>
      </button>
    </li>
  );
}

type MemberListProps = {
  members: Member[];
  period: Period;
  selectedId: string | null;
  onToggle: (memberId: string) => void;
};

export function MemberList({
  members,
  period,
  selectedId,
  onToggle,
}: MemberListProps) {
  const indicatorId = useId();

  return (
    <ul aria-label='Members' className='flex flex-col'>
      {members.map((member) => (
        <MemberRow
          key={member.id}
          member={member}
          period={period}
          isSelected={member.id === selectedId}
          indicatorId={indicatorId}
          onToggle={onToggle}
        />
      ))}
    </ul>
  );
}

'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { useState } from 'react';

import { ChevronDownIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';

import { MEMBERS, type Activity, type ActivityKind, type Member } from './data';
import { IssueTypeGem, MemberAvatar, rowCollapseOf } from './parts';

const COLLAPSED_LIMIT = 4;

const VERBS: Record<ActivityKind, string> = {
  closed: 'closed',
  commented: 'commented on',
  moved: 'moved',
  created: 'created',
};

function memberOf(memberId: string): Member {
  const found = MEMBERS.find((member) => member.id === memberId);
  if (found) {
    return found;
  }
  return MEMBERS[0];
}

function moreLabelOf(hiddenCount: number, isExpanded: boolean) {
  if (isExpanded) {
    return 'Show less';
  }
  if (hiddenCount === 1) {
    return 'Show 1 more';
  }
  return `Show ${hiddenCount} more`;
}

function visibleActivityOf(activity: Activity[], isExpanded: boolean) {
  if (isExpanded) {
    return activity;
  }
  return activity.slice(0, COLLAPSED_LIMIT);
}

function isQuote(activity: Activity) {
  const hasDetail = activity.detail !== undefined;
  const isComment = activity.kind === 'commented';
  return hasDetail && isComment;
}

function suffixOf(activity: Activity) {
  const hasDetail = activity.detail !== undefined;
  const isMove = activity.kind === 'moved';
  if (hasDetail && isMove) {
    return ` ${activity.detail}`;
  }
  return '';
}

function ActivityRow({ activity }: { activity: Activity }) {
  const shouldReduceMotion = useReducedMotion();
  const member = memberOf(activity.memberId);

  return (
    <motion.li
      variants={rowCollapseOf(shouldReduceMotion)}
      initial='hidden'
      animate='shown'
      exit='hidden'
      className='overflow-hidden'
    >
      <div className='flex items-start gap-3 pb-4'>
        <MemberAvatar member={member} />
        <div className='flex min-w-0 flex-1 flex-col gap-1.5'>
          <p className='text-muted-foreground text-[13px] leading-5'>
            <span className='text-foreground font-medium'>{member.name}</span>{' '}
            {VERBS[activity.kind]}{' '}
            <span className='text-foreground inline-flex items-baseline gap-1'>
              <span className='self-center'>
                <IssueTypeGem type={activity.task.type} />
              </span>
              <span className='tabular-nums'>{activity.task.key}</span>
            </span>{' '}
            {activity.task.title}
            {suffixOf(activity)}
          </p>
          {isQuote(activity) && (
            <p className='bg-foreground/[0.025] hairline-ring ring-border rounded-lg px-3 py-2 text-[13px] leading-5'>
              {activity.detail}
            </p>
          )}
        </div>
        <span className='text-muted-foreground shrink-0 text-xs tabular-nums'>
          {activity.age}
        </span>
      </div>
    </motion.li>
  );
}

type ActivityFeedProps = {
  activity: Activity[];
};

export function ActivityFeed({ activity }: ActivityFeedProps) {
  const [isExpanded, setIsExpanded] = useState(false);
  const visible = visibleActivityOf(activity, isExpanded);
  const hiddenCount = activity.length - visible.length;
  const hasMore = activity.length > COLLAPSED_LIMIT;

  function toggleExpanded() {
    setIsExpanded((current) => !current);
  }

  return (
    <div className='flex flex-col'>
      <ul aria-label='Activity' className='flex flex-col'>
        <AnimatePresence initial={false}>
          {visible.map((item) => (
            <ActivityRow key={item.id} activity={item} />
          ))}
        </AnimatePresence>
      </ul>
      {hasMore && (
        <div>
          <Button
            variant='ghost'
            size='sm'
            aria-expanded={isExpanded}
            onClick={toggleExpanded}
            className='text-muted-foreground -ms-2'
          >
            <ChevronDownIcon
              className={cn(
                'transition-transform duration-200 ease-(--ease-out-strong)',
                isExpanded && 'rotate-180'
              )}
            />
            {moreLabelOf(hiddenCount, isExpanded)}
          </Button>
        </div>
      )}
    </div>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import {
  BookmarkIcon,
  CheckIcon,
  CircleAlertIcon,
  ClockIcon,
  MinusIcon,
  MoonIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';

import type { IssueType, Member, Presence, Role } from './data';

type Meta = { label: string; color: string; glyph: Icon };

export const PRESENCE_META: Record<Presence, Meta> = {
  tracking: {
    label: 'Tracking time',
    color: 'var(--primary)',
    glyph: ClockIcon,
  },
  online: { label: 'Online', color: 'var(--success)', glyph: CheckIcon },
  away: { label: 'Away', color: 'var(--warning)', glyph: MoonIcon },
  offline: {
    label: 'Offline',
    color: 'var(--muted-foreground)',
    glyph: MinusIcon,
  },
};

const ISSUE_TYPES: Record<IssueType, Meta> = {
  task: { label: 'Task', color: 'var(--info)', glyph: CheckIcon },
  bug: { label: 'Bug', color: 'var(--destructive)', glyph: CircleAlertIcon },
  story: { label: 'Story', color: 'var(--success)', glyph: BookmarkIcon },
};

export const ROLE_LABELS: Record<Role, string> = {
  manager: 'Manager',
  member: 'Member',
  viewer: 'Viewer',
};

export function formatMinutes(minutes: number) {
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  const restText = String(rest);
  const paddedRest = restText.padStart(2, '0');
  return `${hours}h ${paddedRest}m`;
}

export function TeamTile({
  initials,
  color,
  className,
}: {
  initials: string;
  color: string;
  className?: string;
}) {
  const gemStyle = { '--gem': color } as React.CSSProperties;

  return (
    <span
      aria-hidden='true'
      style={gemStyle}
      className={cn(
        'gem-plate inline-flex size-10 shrink-0 items-center justify-center rounded-xl text-sm font-semibold',
        className
      )}
    >
      {initials}
    </span>
  );
}

export function IssueTypeGem({ type }: { type: IssueType }) {
  const meta = ISSUE_TYPES[type];
  const Glyph = meta.glyph;
  const gemStyle = { '--gem': meta.color } as React.CSSProperties;

  return (
    <span
      role='img'
      aria-label={meta.label}
      style={gemStyle}
      className='gem-plate inline-flex size-4 shrink-0 items-center justify-center rounded-[5px]'
    >
      <Glyph strokeWidth={2.5} className='size-2.5' />
    </span>
  );
}

export function MemberAvatar({
  member,
  className,
}: {
  member: Member;
  className?: string;
}) {
  return (
    <Avatar className={cn('size-7 text-[10px]', className)}>
      {member.avatar && <AvatarImage src={member.avatar} alt='' />}
      <AvatarFallback>{member.initials}</AvatarFallback>
    </Avatar>
  );
}

/** A face with the person's presence as a small glyph on its corner, read out after the name. */
export function PresenceAvatar({ member }: { member: Member }) {
  const presence = PRESENCE_META[member.presence];
  const Glyph = presence.glyph;
  const badgeStyle = { '--chip': presence.color } as React.CSSProperties;

  return (
    <span className='relative inline-flex shrink-0'>
      <MemberAvatar member={member} className='size-8 text-[11px]' />
      <span
        aria-hidden='true'
        className='bg-card absolute -end-0.5 -bottom-0.5 flex rounded-full p-px'
      >
        <span
          style={badgeStyle}
          className='chip-3d flex size-3.5 items-center justify-center rounded-full'
        >
          <Glyph className='size-2' strokeWidth={2.75} />
        </span>
      </span>
      <span className='sr-only'>{presence.label}</span>
    </span>
  );
}

const EASE_OUT_STRONG: [number, number, number, number] = [0.23, 1, 0.32, 1];

/** The spring AnimatedSize resizes with, so rows close at the pace their list follows. */
const SIZE_SPRING: Transition = { type: 'spring', bounce: 0, duration: 0.32 };

const ROW_VARIANTS: Variants = {
  shown: {
    height: 'auto',
    opacity: 1,
    transition: {
      ...SIZE_SPRING,
      opacity: { duration: 0.2, ease: EASE_OUT_STRONG },
    },
  },
  hidden: {
    height: 0,
    opacity: 0,
    transition: {
      ...SIZE_SPRING,
      opacity: { duration: 0.12, ease: EASE_OUT_STRONG },
    },
  },
};

const FADE_VARIANTS: Variants = {
  shown: { opacity: 1, transition: { duration: 0.2, ease: EASE_OUT_STRONG } },
  hidden: { opacity: 0, transition: { duration: 0.12, ease: EASE_OUT_STRONG } },
};

export function rowCollapseOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return ROW_VARIANTS;
}

const SHIFT_PX = 8;

const SLIDE_TRANSITION: Transition = { duration: 0.18, ease: [0.2, 0, 0, 1] };

const SLIDE_VARIANTS: Variants = {
  enter: (direction: number) => {
    const offset = direction * SHIFT_PX;
    return { opacity: 0, y: offset };
  },
  visible: { opacity: 1, y: 0 },
  exit: (direction: number) => {
    const offset = direction * SHIFT_PX;
    return { opacity: 0, y: -offset };
  },
};

const SLIDE_FADE: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

function slideVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return SLIDE_FADE;
  }
  return SLIDE_VARIANTS;
}

function directionOf(previous: number, next: number) {
  if (next > previous) {
    return 1;
  }
  return -1;
}

type Shown = { value: number; direction: number };

/** A figure that changed under the person's choice: it slides in the direction of the change. */
export function SlidingFigure({
  value,
  format,
  className,
}: {
  value: number;
  format: (value: number) => string;
  className?: string;
}) {
  const shouldReduceMotion = useReducedMotion();
  const [shown, setShown] = useState<Shown>({ value, direction: 1 });
  const text = format(value);

  if (shown.value !== value) {
    const direction = directionOf(shown.value, value);
    setShown({ value, direction });
  }

  return (
    <span
      className={cn(
        'relative inline-flex overflow-hidden tabular-nums',
        className
      )}
    >
      <AnimatePresence
        mode='popLayout'
        initial={false}
        custom={shown.direction}
      >
        <motion.span
          key={text}
          custom={shown.direction}
          variants={slideVariantsOf(shouldReduceMotion)}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SLIDE_TRANSITION}
          className='whitespace-nowrap'
        >
          {text}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

